// The world and the cards' lore, in data/world.json and data/lore.json. Both were generated by a
// build-time script from the zendikar-map project's data.
//
// world.json: coastlines and places. The coastline is the project's own trace; positions are the
// project's reading, not an official map.
// lore.json: every ZEN card of saga 1 phase 1 and every ZEN non-basic land. Official English
// names, official Korean names where one was printed (ko: null otherwise), set number, rarity,
// type line, and the continent and place the map project ties the card to.
import worldJson from '../../data/world.json';
import loreJson from '../../data/lore.json';

/** A place the expedition can go. x, y: on the game's map; ux, uy: in the map project's units. */
export interface Stop {
  id: string;
  /** town, wild, elite or camp. */
  cls: string;
  cont: string;
  x: number;
  y: number;
  ux: number;
  uy: number;
  en: string;
  ko: string | null;
  kind: string;
}

/** A continent's names, and where the map project puts its label (in its units). */
export interface Continent {
  en: string;
  ko: string;
  label?: { at: number[] };
}

/** An outline: x, y, x, y, ... in the game's map pixels. */
export interface Outline {
  id: string;
  pts: number[];
}

export interface World {
  w: number;
  h: number;
  /** Map project units to the game's map pixels. */
  scale: number;
  lands: Outline[];
  forests: number[][];
  waters: Outline[];
  continents: Record<string, Continent>;
  stops: Stop[];
}

/** What the map project records for a card. */
export interface Lore {
  en: string;
  ko: string | null;
  set: string;
  no: string;
  rarity: string;
  type: string;
  cont: string | null;
  placeEn: string | null;
  placeKo: string | null;
  land?: boolean;
}

export const WORLD: World = worldJson;
export const LORE: Record<string, Lore> = loreJson;
